import React, { useEffect, useState } from "react";
import { db } from "../firebase";
import { collection, onSnapshot, doc, updateDoc } from "firebase/firestore";
import MapView from "./MapView";

function FoodList() {
  const [foods, setFoods] = useState([]);
  const [userLocation, setUserLocation] = useState(null);

  useEffect(() => {
    const unsub = onSnapshot(collection(db, "foods"), (snapshot) => {
      setFoods(snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })));
    });

    navigator.geolocation.getCurrentPosition((pos) => {
      setUserLocation({
        lat: pos.coords.latitude,
        lng: pos.coords.longitude
      });
    });

    return () => unsub();
  }, []);

  const reserve = async (id) => {
    await updateDoc(doc(db, "foods", id), {
      status: "reserved"
    });
  };

  const mealsSaved = foods.filter(f => f.status !== "available").length;

  function getDistance(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;

    const a =
      Math.sin(dLat/2) ** 2 +
      Math.cos(lat1 * Math.PI/180) *
      Math.cos(lat2 * Math.PI/180) *
      Math.sin(dLon/2) ** 2;

    return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a)));
  }

  return (
    <div>
      <h2>🍽️ Meals Saved: {mealsSaved}</h2>

      <MapView foods={foods} reserve={reserve} />

      {foods.map(food => (
        <div className="card" key={food.id}>
          <h3>{food.name}</h3>
          <p>{food.user}</p>

          <p>
            {userLocation && food.location
              ? getDistance(
                  userLocation.lat,
                  userLocation.lng,
                  food.location.lat,
                  food.location.lng
                ).toFixed(2) + " km away"
              : ""}
          </p>

          <button
            style={{
              background: food.status === "available" ? "#22c55e" : "#ef4444"
            }}
            onClick={() => reserve(food.id)}
          >
            {food.status}
          </button>
        </div>
      ))}
    </div>
  );
}

export default FoodList;
